protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> pathEdges = new ArrayList<>(tour);
    if (pathEdges.isEmpty()) {
        return new GraphPathImpl<>(graph, null, pathEdges, 0.0);
    }

    // Assuming GraphPathImpl is a class that implements GraphPath
    // and can be constructed with the given parameters.
    // The cost is assumed to be calculated as the sum of edge weights.
    double cost = 0.0;
    for (E edge : pathEdges) {
        cost += graph.getEdgeWeight(edge);
    }

    V startVertex = graph.getEdgeSource(pathEdges.get(0));
    return new GraphPathImpl<>(graph, startVertex, pathEdges, cost);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0);
    }

    Map<V, E> incomingEdges = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (incomingEdges.containsKey(target)) {
            throw new IllegalArgumentException("Not a valid tour: multiple incoming edges to a single vertex");
        }
        incomingEdges.put(target, edge);
    }

    E startEdge = null;
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        if (!incomingEdges.containsKey(source)) {
            startEdge = edge;
            break;
        }
    }

    if (startEdge == null) {
        throw new IllegalArgumentException("Not a valid tour: could not find a starting edge");
    }

    List<E> pathEdges = new ArrayList<>();
    List<V> pathVertices = new ArrayList<>();
    double pathWeight = 0;
    V currentVertex = graph.getEdgeTarget(startEdge);
    E currentEdge = startEdge;

    while (currentEdge != null) {
        pathEdges.add(currentEdge);
        pathVertices.add(currentVertex);
        pathWeight += graph.getEdgeWeight(currentEdge);
        currentVertex = graph.getEdgeSource(currentEdge);
        currentEdge = incomingEdges.get(currentVertex);
    }

    // Add the first vertex to close the path
    pathVertices.add(pathVertices.get(0));

    return new GraphPathImpl<>(graph, graph.getEdgeTarget(startEdge), pathEdges, pathWeight);
}

// Assuming GraphPathImpl is a class that implements GraphPath interface
class GraphPathImpl<V, E> implements GraphPath<V, E> {
    private final Graph<V, E> graph;
    private final V startVertex;
    private final List<E> edgeList;
    private final double weight;

    public GraphPathImpl(Graph<V, E> graph, V startVertex, List<E> edgeList, double weight) {
        this.graph = graph;
        this.startVertex = startVertex;
        this.edgeList = Collections.unmodifiableList(edgeList);
        this.weight = weight;
    }

    @Override
    public Graph<V, E> getGraph() {
        return graph;
    }

    @Override
    public V getStartVertex() {
        return startVertex;
    }

    @Override
    public V getEndVertex() {
        return startVertex; // Assuming the path is a cycle
    }

    @Override
    public List<E> getEdgeList() {
        return edgeList;
    }

    @Override
    public List<V> getVertexList() {
        List<V> vertexList = new ArrayList<>();
        V currentVertex = startVertex;
        for (E edge : edgeList) {
            vertexList.add(currentVertex);
            currentVertex = Graphs.getOppositeVertex(graph, edge, currentVertex);
        }
        vertexList.add(currentVertex); // Add the last vertex to close the cycle
        return vertexList;
    }

    @Override
    public double getWeight() {
        return weight;
    }
}

