String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Normalize the paths by replacing backslashes with forward slashes
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Use a stack to build the final path
    Stack<String> stack = new Stack<>();
    for (String component : pathComponents) {
        if (!component.isEmpty()) {
            stack.push(component);
        }
    }

    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else if (component.equals(".")) {
            // Current directory, do nothing
        } else if (!component.isEmpty()) {
            stack.push(component);
        }
    }

    // Join the components back into a path
    StringBuilder result = new StringBuilder();
    while (!stack.isEmpty()) {
        result.insert(0, stack.pop());
        if (!stack.isEmpty()) {
            result.insert(0, "/");
        }
    }

    // Determine if the original path started with a slash and add it if necessary
    if (path.startsWith("/") && !result.toString().startsWith("/")) {
        result.insert(0, "/");
    }

    return result.toString();
}

