    }

    // Normalize the paths to handle any trailing slashes
    String normalizedPath = path.endsWith("/") ? path.substring(0, path.length() - 1) : path;
    String normalizedRelativePath = relativePath.startsWith("/") ? relativePath.substring(1) : relativePath;

    // Split the paths into components
    String[] pathComponents = normalizedPath.split("/");
    String[] relativeComponents = normalizedRelativePath.split("/");

    // Apply the relative path logic
    int pathIndex = pathComponents.length;
    for (String component : relativeComponents) {
        if (component.equals("..")) {
            if (pathIndex > 0) {
                pathIndex--;
            }
        } else if (!component.equals(".")) {
            // Skip the current directory marker "."
            String[] temp = new String[pathIndex + 1];
            System.arraycopy(pathComponents, 0, temp, 0, pathIndex);
            temp[pathIndex] = component;
            pathComponents = temp;
            pathIndex++;
        }
    }

    // Reconstruct the path
    StringBuilder resultPath = new StringBuilder();
    for (int i = 0; i < pathIndex; i++) {
        if (i > 0) {
            resultPath.append("/");
