long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    try {
        int year = (int) (timeBucket / 10000);
        int monthDay = (int) (timeBucket % 10000);
        int month = monthDay / 100;
        int day = monthDay % 100;

        // Calculate the day of the month that is a multiple of dayStep
        int newDay = (day - 1) / dayStep * dayStep + 1;

        return year * 10000 + month * 100 + newDay;
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid timeBucket format: " + timeBucket, e);
    }
}

