long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        int startDate = day - (day - 1) % dayStep;
        if (startDate < 1) {
            startDate += dayStep;
            Calendar calendar = Calendar.getInstance();
            calendar.set(year, month - 1, 1);
            calendar.add(Calendar.MONTH, -1);
            year = calendar.get(Calendar.YEAR);
            month = calendar.get(Calendar.MONTH) + 1;
            int daysInLastMonth = calendar.getActualMaximum(Calendar.DAY_OF_MONTH);
            startDate = daysInLastMonth - (daysInLastMonth - 1) % dayStep;
