        int dayOffset = (day - 1) / dayStep;

        // Calculate the new day
        int newDay = dayOffset * dayStep + 1;

        // Ensure the new day is within the month
        if (newDay < 1 || newDay > 31) {
            throw new IllegalArgumentException("Invalid day calculated after compression.");
