                }
                // Assuming pop() is a method to pop the top element from the stack
                pop();
            }
        } else {
            // It's a type descriptor
            switch (descriptor.charAt(0)) {
                case 'B':
                case 'C':
                case 'D':
                case 'F':
                case 'I':
                case 'J':
                case 'S':
                case 'Z':
                case 'L':
                case '[':
                    pop();
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type descriptor: " + descriptor);
            }
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
