int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new NullPointerException("Message cannot be null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new NullPointerException("LinkedBuffer cannot be null");
    }

    try {
        // Calculate the message length and write it to the output stream as a varint
        int messageLength = (int) schema.getSerializedSize(message, buffer);
        byte[] lengthBytes = CodedOutputStream.newInstance(new byte[10], 0, 10).writeVarInt32NoTagToByteArray(messageLength);
        out.write(lengthBytes);

        // Serialize the message to the output stream
        schema.writeTo(out, message, buffer);
        return messageLength;
    } catch (IOException e) {
        throw e;
    } finally {
        buffer.clear();
    }
}

