LinkedBuffer ensureCapacity(int required, LinkedBuffer lb) {
    if (lb.offset + required > lb.buffer.length) {
        int newSize = lb.buffer.length == 0 ? 16 : lb.buffer.length * 2;
        while (newSize < lb.offset + required) {
            newSize *= 2;
        }
        byte[] newBuffer = new byte[newSize];
        System.arraycopy(lb.buffer, 0, newBuffer, 0, lb.offset);
        return new LinkedBuffer(newBuffer, lb.offset, lb.next);
    }
